from pathlib import Path
import shutil
from datetime import datetime

ROOT = Path.cwd().resolve()

if not (ROOT / "solve.py").exists():
    raise SystemExit(
        "ERROR: Run this installer from the RS42 repository root."
    )

TARGET = (
    ROOT
    / "tools"
    / "final_evaluation"
    / "build_e5_mixed_preferences.py"
)

if TARGET.exists():
    stamp = datetime.now().strftime(
        "%Y%m%d_%H%M%S"
    )

    backup = TARGET.with_name(
        "build_e5_before_solver_safe_{}.py"
        .format(stamp)
    )

    shutil.copy2(
        str(TARGET),
        str(backup),
    )

    print(
        "Backup:",
        backup.relative_to(ROOT),
    )

BUILDER = '"""\nRS42 E5 — Final Solver-Safe Mixed Preference Network.\n\nThis is the final E5 geometry.\n\nIt is deliberately larger and more complex than the original validated E5,\nbut kept below the route/horizon size that caused the 300-second timeout.\n\nPassenger alternatives:\n\nA) Fast multi-transfer\n   movement: 5 + 5 + 5\n   journey: 17\n   wait: 2\n   transfers: 2\n   route turns: high\n\nB) Direct\n   movement: 22\n   journey: 22\n   wait: 0\n   transfers: 0\n   route turns: medium\n\nC) Compromise\n   movement: 9 + 10\n   journey: 20\n   wait: 1\n   transfers: 1\n   route turns: low\n\nExpected semantic behavior:\n- Fastest -> A\n- Less Waiting -> B\n- Fewer Transfers -> B\n- Simple Journey -> C\n- Balanced is measured in the final evaluation.\n"""\n\nfrom __future__ import annotations\n\nimport argparse\nimport json\nimport pickle\nimport sys\nimport tempfile\nfrom pathlib import Path\n\nROOT = Path(__file__).resolve().parents[2]\n\nif str(ROOT) not in sys.path:\n    sys.path.insert(0, str(ROOT))\n\nfrom modules.convert import convert_to_clingo\nfrom modules.save import save_png\n\nfrom flatland.envs.rail_generators import rail_from_grid_transition_map\nfrom flatland.envs.rail_env import RailEnv\nfrom flatland.envs.observations import GlobalObsForRailEnv\nfrom flatland.envs.malfunction_generators import (\n    MalfunctionParameters,\n    ParamMalfunctionGen,\n)\n\nfrom tools.final_evaluation.evaluation_generators import (\n    EvaluationLineGenerator,\n)\n\nfrom tools.final_evaluation.final_eval_rail_geometry import (\n    build_disjoint_rail,\n    initial_direction,\n    manhattan_path,\n    route_steps,\n    route_turns,\n)\n\nfrom tools.final_evaluation.final_eval_builder_common import (\n    chosen_legs,\n    metric_show_text,\n    passenger_metric,\n    profile_path,\n    require_backend,\n    run_clingo,\n)\n\n\nSTEM = "e5_mixed_preferences"\n\nWIDTH = 22\nHEIGHT = 22\nHORIZON = 30\n\n\n# ----------------------------------------------------------------------\n# Physical routes\n# ----------------------------------------------------------------------\n\n# Direct: 22 evaluated movement steps, 7 turns.\nDIRECT = manhattan_path([\n    (2, 0),\n    (2, 5),\n    (5, 5),\n    (5, 8),\n    (3, 8),\n    (3, 11),\n    (6, 11),\n    (6, 14),\n    (4, 14),\n])\n\n\n# Fast route: three five-step zig-zag services.\n# Each has four route turns.\nFAST1 = manhattan_path([\n    (9, 0),\n    (9, 2),\n    (8, 2),\n    (8, 3),\n    (9, 3),\n    (9, 5),\n])\n\nFAST2 = manhattan_path([\n    (9, 7),\n    (9, 9),\n    (10, 9),\n    (10, 10),\n    (9, 10),\n    (9, 12),\n])\n\nFAST3 = manhattan_path([\n    (9, 14),\n    (9, 16),\n    (8, 16),\n    (8, 17),\n    (9, 17),\n    (9, 19),\n])\n\n\n# Compromise route: longer individual legs but only two turns per service.\nCOMP1 = manhattan_path([\n    (16, 0),\n    (16, 4),\n    (19, 4),\n    (19, 8),\n])\n\nCOMP2 = manhattan_path([\n    (20, 10),\n    (20, 14),\n    (16, 14),\n    (16, 18),\n])\n\n\nPATHS = [\n    DIRECT,\n    FAST1,\n    FAST2,\n    FAST3,\n    COMP1,\n    COMP2,\n]\n\n\nSTARTS = [\n    (2, 1),\n    (9, 1),\n    (9, 8),\n    (9, 15),\n    (16, 1),\n    (20, 11),\n]\n\n\nTARGETS = [\n    (5, 14),\n    (9, 4),\n    (9, 11),\n    (9, 18),\n    (19, 7),\n    (16, 17),\n]\n\n\n# first_station_visit for a starting station occurs at release + 2.\n#\n# Fast:\n#   2 -> 7\n#   8 -> 13\n#   14 -> 19\n#\n# Compromise:\n#   2 -> 11\n#   12 -> 22\nRELEASES = [\n    0,\n    0,\n    6,\n    12,\n    0,\n    10,\n]\n\n\nSTEPS = [\n    route_steps(path, start, target)\n    for path, start, target\n    in zip(PATHS, STARTS, TARGETS)\n]\n\n\nTURNS = [\n    route_turns(path, start, target)\n    for path, start, target\n    in zip(PATHS, STARTS, TARGETS)\n]\n\n\nOUT_PKL = ROOT / "envs" / "pkl" / f"{STEM}.pkl"\nOUT_LP = ROOT / "envs" / "lp" / f"{STEM}.lp"\nOUT_PNG = ROOT / "envs" / "png" / f"{STEM}.png"\n\nOUT_SCENARIO = (\n    ROOT\n    / "asp"\n    / "scenarios"\n    / f"{STEM}.lp"\n)\n\nOUT_META = (\n    ROOT\n    / "experiments"\n    / "final_evaluation"\n    / "configs"\n    / f"{STEM}.json"\n)\n\n\ndef parse_args():\n    parser = argparse.ArgumentParser()\n\n    parser.add_argument(\n        "--overwrite",\n        action="store_true",\n    )\n\n    parser.add_argument(\n        "--full-check",\n        action="store_true",\n        help=(\n            "Also run Balanced during builder validation. "\n            "The default build checks the four controlled semantic profiles."\n        ),\n    )\n\n    return parser.parse_args()\n\n\ndef validate_geometry():\n    expected_steps = [\n        22,\n        5,\n        5,\n        5,\n        9,\n        10,\n    ]\n\n    expected_turns = [\n        7,\n        4,\n        4,\n        4,\n        2,\n        2,\n    ]\n\n    if STEPS != expected_steps:\n        raise RuntimeError(\n            "Unexpected E5 movement lengths: {} "\n            "(expected {})".format(\n                STEPS,\n                expected_steps,\n            )\n        )\n\n    if TURNS != expected_turns:\n        raise RuntimeError(\n            "Unexpected E5 route turns: {} "\n            "(expected {})".format(\n                TURNS,\n                expected_turns,\n            )\n        )\n\n    # Explicitly enforce a buffer rail cell before every start\n    # and after every target.\n    for index, (\n        path,\n        start,\n        target,\n    ) in enumerate(\n        zip(\n            PATHS,\n            STARTS,\n            TARGETS,\n        )\n    ):\n        start_index = path.index(start)\n        target_index = path.index(target)\n\n        if start_index <= 0:\n            raise RuntimeError(\n                "route{} start {} has no leading rail buffer."\n                .format(\n                    index,\n                    start,\n                )\n            )\n\n        if target_index >= len(path) - 1:\n            raise RuntimeError(\n                "route{} target {} has no trailing rail buffer."\n                .format(\n                    index,\n                    target,\n                )\n            )\n\n\ndef build_environment():\n    rail = build_disjoint_rail(\n        WIDTH,\n        HEIGHT,\n        {\n            "direct": DIRECT,\n            "fast1": FAST1,\n            "fast2": FAST2,\n            "fast3": FAST3,\n            "comp1": COMP1,\n            "comp2": COMP2,\n        },\n    )\n\n    env = RailEnv(\n        width=WIDTH,\n        height=HEIGHT,\n        rail_generator=rail_from_grid_transition_map(\n            rail\n        ),\n        line_generator=EvaluationLineGenerator(\n            positions=STARTS,\n            directions=[\n                initial_direction(\n                    path,\n                    start,\n                )\n                for path, start\n                in zip(\n                    PATHS,\n                    STARTS,\n                )\n            ],\n            targets=TARGETS,\n            speeds=[1.0] * 6,\n        ),\n        number_of_agents=6,\n        obs_builder_object=GlobalObsForRailEnv(),\n        malfunction_generator=ParamMalfunctionGen(\n            MalfunctionParameters(\n                0.0,\n                0,\n                0,\n            )\n        ),\n        remove_agents_at_target=True,\n        random_seed=42,\n    )\n\n    env.reset(\n        random_seed=42\n    )\n\n    env._max_episode_steps = HORIZON\n\n    for agent, release, steps in zip(\n        env.agents,\n        RELEASES,\n        STEPS,\n    ):\n        agent.earliest_departure = release\n\n        try:\n            agent.latest_arrival = (\n                release\n                + 2\n                + steps\n            )\n        except Exception:\n            pass\n\n    return env\n\n\ndef scenario_text():\n    coords = list(\n        zip(\n            STARTS,\n            TARGETS,\n        )\n    )\n\n    return f"""% RS42 E5 - Final Solver-Safe Mixed Preference Network\n\n% ------------------------------------------------------------------\n% Direct service - Train 0\n% ------------------------------------------------------------------\n\nflatland_waypoint(\n    0,\n    wp_d_o,\n    {coords[0][0][0]},\n    {coords[0][0][1]}\n).\n\nflatland_waypoint(\n    0,\n    wp_d_d,\n    {coords[0][1][0]},\n    {coords[0][1][1]}\n).\n\nstation(origin,0,wp_d_o).\nstation(destination,0,wp_d_d).\n\nmust_visit(0,origin).\nmust_visit(0,destination).\n\nstation_order(\n    0,\n    origin,\n    destination\n).\n\n\n% ------------------------------------------------------------------\n% Fast multi-transfer journey - Trains 1 -> 2 -> 3\n% ------------------------------------------------------------------\n\nflatland_waypoint(\n    1,\n    wp_f1_o,\n    {coords[1][0][0]},\n    {coords[1][0][1]}\n).\n\nflatland_waypoint(\n    1,\n    wp_f1_b,\n    {coords[1][1][0]},\n    {coords[1][1][1]}\n).\n\nstation(origin,1,wp_f1_o).\nstation(station_b,1,wp_f1_b).\n\nmust_visit(1,origin).\nmust_visit(1,station_b).\n\nstation_order(\n    1,\n    origin,\n    station_b\n).\n\n\nflatland_waypoint(\n    2,\n    wp_f2_b,\n    {coords[2][0][0]},\n    {coords[2][0][1]}\n).\n\nflatland_waypoint(\n    2,\n    wp_f2_c,\n    {coords[2][1][0]},\n    {coords[2][1][1]}\n).\n\nstation(station_b,2,wp_f2_b).\nstation(station_c,2,wp_f2_c).\n\nmust_visit(2,station_b).\nmust_visit(2,station_c).\n\nstation_order(\n    2,\n    station_b,\n    station_c\n).\n\n\nflatland_waypoint(\n    3,\n    wp_f3_c,\n    {coords[3][0][0]},\n    {coords[3][0][1]}\n).\n\nflatland_waypoint(\n    3,\n    wp_f3_d,\n    {coords[3][1][0]},\n    {coords[3][1][1]}\n).\n\nstation(station_c,3,wp_f3_c).\nstation(destination,3,wp_f3_d).\n\nmust_visit(3,station_c).\nmust_visit(3,destination).\n\nstation_order(\n    3,\n    station_c,\n    destination\n).\n\n\n% ------------------------------------------------------------------\n% Compromise journey - Trains 4 -> 5\n% ------------------------------------------------------------------\n\nflatland_waypoint(\n    4,\n    wp_c1_o,\n    {coords[4][0][0]},\n    {coords[4][0][1]}\n).\n\nflatland_waypoint(\n    4,\n    wp_c1_h,\n    {coords[4][1][0]},\n    {coords[4][1][1]}\n).\n\nstation(origin,4,wp_c1_o).\nstation(station_h,4,wp_c1_h).\n\nmust_visit(4,origin).\nmust_visit(4,station_h).\n\nstation_order(\n    4,\n    origin,\n    station_h\n).\n\n\nflatland_waypoint(\n    5,\n    wp_c2_h,\n    {coords[5][0][0]},\n    {coords[5][0][1]}\n).\n\nflatland_waypoint(\n    5,\n    wp_c2_d,\n    {coords[5][1][0]},\n    {coords[5][1][1]}\n).\n\nstation(station_h,5,wp_c2_h).\nstation(destination,5,wp_c2_d).\n\nmust_visit(5,station_h).\nmust_visit(5,destination).\n\nstation_order(\n    5,\n    station_h,\n    destination\n).\n\n\npassenger(p1).\npassenger_origin(\n    p1,\n    origin\n).\n\npassenger_destination(\n    p1,\n    destination\n).\n\n\n% ------------------------------------------------------------------\n% Fixed timetable.\n%\n% Direct:\n%   2 -> 24\n%   journey = 22\n%   wait = 0\n%   transfers = 0\n%\n% Fast:\n%   2 -> 7\n%   8 -> 13\n%   14 -> 19\n%   journey = 17\n%   wait = 2\n%   transfers = 2\n%\n% Compromise:\n%   2 -> 11\n%   12 -> 22\n%   journey = 20\n%   wait = 1\n%   transfers = 1\n% ------------------------------------------------------------------\n\n:- first_station_visit(\n    0,\n    origin,\n    T\n),\nT != 2.\n\n:- first_station_visit(\n    0,\n    destination,\n    T\n),\nT != 24.\n\n\n:- first_station_visit(\n    1,\n    origin,\n    T\n),\nT != 2.\n\n:- first_station_visit(\n    1,\n    station_b,\n    T\n),\nT != 7.\n\n\n:- first_station_visit(\n    2,\n    station_b,\n    T\n),\nT != 8.\n\n:- first_station_visit(\n    2,\n    station_c,\n    T\n),\nT != 13.\n\n\n:- first_station_visit(\n    3,\n    station_c,\n    T\n),\nT != 14.\n\n:- first_station_visit(\n    3,\n    destination,\n    T\n),\nT != 19.\n\n\n:- first_station_visit(\n    4,\n    origin,\n    T\n),\nT != 2.\n\n:- first_station_visit(\n    4,\n    station_h,\n    T\n),\nT != 11.\n\n\n:- first_station_visit(\n    5,\n    station_h,\n    T\n),\nT != 12.\n\n:- first_station_visit(\n    5,\n    destination,\n    T\n),\nT != 22.\n"""\n\n\ndef evaluate(\n    env_lp_text,\n    scenario,\n    full_check=False,\n):\n    with tempfile.TemporaryDirectory() as tmp:\n        tmpdir = Path(tmp)\n\n        env_lp = (\n            tmpdir\n            / "environment.lp"\n        )\n\n        scenario_file = (\n            tmpdir\n            / "scenario.lp"\n        )\n\n        show_file = (\n            tmpdir\n            / "show.lp"\n        )\n\n        env_lp.write_text(\n            env_lp_text,\n            encoding="utf-8",\n        )\n\n        scenario_file.write_text(\n            scenario,\n            encoding="utf-8",\n        )\n\n        show_file.write_text(\n            metric_show_text(),\n            encoding="utf-8",\n        )\n\n        profiles = [\n            "fastest",\n            "least_waiting",\n            "fewest_transfers",\n            "simple",\n        ]\n\n        if full_check:\n            profiles.append(\n                "balanced"\n            )\n\n        results = {}\n\n        for profile in profiles:\n            print(\n                "  checking {}..."\n                .format(profile)\n            )\n\n            status, atoms, costs = run_clingo(\n                ROOT,\n                env_lp,\n                scenario_file,\n                profile_path(\n                    ROOT,\n                    profile,\n                ),\n                show_file,\n                timeout=150,\n            )\n\n            results[profile] = {\n                "status": status,\n                "journey": passenger_metric(\n                    atoms,\n                    "passenger_journey_time",\n                ),\n                "wait": passenger_metric(\n                    atoms,\n                    "passenger_transfer_wait",\n                ),\n                "transfers": passenger_metric(\n                    atoms,\n                    "transfer_count",\n                ),\n                "legs": chosen_legs(\n                    atoms\n                ),\n                "costs": costs,\n            }\n\n        return results\n\n\ndef validate_results(results):\n    fastest = results[\n        "fastest"\n    ]\n\n    least = results[\n        "least_waiting"\n    ]\n\n    fewest = results[\n        "fewest_transfers"\n    ]\n\n    simple = results[\n        "simple"\n    ]\n\n    if not (\n        fastest["journey"] == 17\n        and fastest["wait"] == 2\n        and fastest["transfers"] == 2\n    ):\n        raise RuntimeError(\n            "E5 Fastest check failed: {}"\n            .format(\n                fastest\n            )\n        )\n\n    if not (\n        least["journey"] == 22\n        and least["wait"] == 0\n        and least["transfers"] == 0\n    ):\n        raise RuntimeError(\n            "E5 Less Waiting check failed: {}"\n            .format(\n                least\n            )\n        )\n\n    if not (\n        fewest["journey"] == 22\n        and fewest["transfers"] == 0\n    ):\n        raise RuntimeError(\n            "E5 Fewer Transfers check failed: {}"\n            .format(\n                fewest\n            )\n        )\n\n    if not (\n        simple["journey"] == 20\n        and simple["transfers"] == 1\n    ):\n        raise RuntimeError(\n            "E5 Simple Journey check failed: {}"\n            .format(\n                simple\n            )\n        )\n\n\ndef save_outputs(\n    env,\n    env_lp_text,\n    scenario,\n    results,\n):\n    for path in [\n        OUT_PKL,\n        OUT_LP,\n        OUT_PNG,\n        OUT_SCENARIO,\n        OUT_META,\n    ]:\n        path.parent.mkdir(\n            parents=True,\n            exist_ok=True,\n        )\n\n    with OUT_PKL.open(\n        "wb"\n    ) as handle:\n        pickle.dump(\n            env,\n            handle,\n            protocol=pickle.HIGHEST_PROTOCOL,\n        )\n\n    OUT_LP.write_text(\n        env_lp_text,\n        encoding="utf-8",\n    )\n\n    OUT_SCENARIO.write_text(\n        scenario,\n        encoding="utf-8",\n    )\n\n    OUT_META.write_text(\n        json.dumps(\n            {\n                "environment": STEM,\n                "purpose": (\n                    "integrated mixed-preference "\n                    "passenger network"\n                ),\n                "geometry_version": (\n                    "solver_safe_final_v1"\n                ),\n                "movement_steps": STEPS,\n                "route_turns": TURNS,\n                "expected_passenger_options": {\n                    "fast": {\n                        "journey": 17,\n                        "wait": 2,\n                        "transfers": 2,\n                    },\n                    "direct": {\n                        "journey": 22,\n                        "wait": 0,\n                        "transfers": 0,\n                    },\n                    "compromise": {\n                        "journey": 20,\n                        "wait": 1,\n                        "transfers": 1,\n                    },\n                },\n                "builder_checks": results,\n            },\n            indent=2,\n        )\n        + "\\n",\n        encoding="utf-8",\n    )\n\n    prefix = (\n        str(ROOT / "envs")\n        + str(Path("/"))\n    )\n\n    save_png(\n        env,\n        STEM,\n        prefix,\n    )\n\n\ndef main():\n    args = parse_args()\n\n    require_backend(\n        ROOT\n    )\n\n    validate_geometry()\n\n    if (\n        OUT_PKL.exists()\n        and not args.overwrite\n    ):\n        raise RuntimeError(\n            "E5 exists. Use --overwrite "\n            "to intentionally rebuild."\n        )\n\n    print(\n        "Building final solver-safe E5..."\n    )\n\n    print(\n        "  movement steps:",\n        STEPS,\n    )\n\n    print(\n        "  route turns:",\n        TURNS,\n    )\n\n    env = build_environment()\n\n    env_lp_text = convert_to_clingo(\n        env\n    )\n\n    scenario = scenario_text()\n\n    results = evaluate(\n        env_lp_text,\n        scenario,\n        full_check=args.full_check,\n    )\n\n    validate_results(\n        results\n    )\n\n    save_outputs(\n        env,\n        env_lp_text,\n        scenario,\n        results,\n    )\n\n    print()\n    print(\n        "E5 FINAL BUILD: PASS"\n    )\n\n    for profile, result in results.items():\n        print(\n            "  {}: journey={}, "\n            "wait={}, transfers={}"\n            .format(\n                profile,\n                result["journey"],\n                result["wait"],\n                result["transfers"],\n            )\n        )\n\n    print()\n    print(\n        "  PNG:",\n        OUT_PNG.relative_to(ROOT),\n    )\n\n\nif __name__ == "__main__":\n    try:\n        main()\n    except Exception as exc:\n        print(\n            "ERROR:",\n            exc,\n            file=sys.stderr,\n        )\n        raise SystemExit(1)\n'

compile(
    BUILDER,
    str(TARGET),
    "exec",
)

TARGET.write_text(
    BUILDER,
    encoding="utf-8",
)

print(
    "E5 SOLVER-SAFE BUILDER: INSTALLED"
)

print(
    "Target:",
    TARGET.relative_to(ROOT),
)

print()
print(
    "Run:"
)

print(
    r"  python tools\final_evaluation\build_e5_mixed_preferences.py --overwrite"
)
